# We need to walk the AST directly
from tree_sitter import Language, Parser, Node
import tree_sitter_c as tsc
C_LANGUAGE = Language(tsc.language())

src = b'void schedule(void) { int x; }\nvoid do_fork(void) { schedule(); }'
parser = Parser(C_LANGUAGE)
tree = parser.parse(src)
root = tree.root_node

# Walk finding function definitions  
def find_nodes_by_type(root, node_type):
    results = []
    def walk(node):
        if node.type == node_type:
            results.append(node)
        for child in node.children:
            walk(child)
    walk(root)
    return results

fns = find_nodes_by_type(root, 'function_definition')
for fn in fns:
    # Get function name
    for child in fn.children:
        if child.type == 'function_declarator':
            for sub in child.children:
                if sub.type == 'identifier':
                    print('Function:', sub.text.decode())
" 2>&1

