from tree_sitter import Language, Parser, Node
import tree_sitter_c as tsc
C_LANGUAGE = Language(tsc.language())

src = b'''
#define MAX_PRIO 140
#include <linux/sched.h>
struct task_struct { int pid; char comm[16]; };
union ktime { long tv64; };
enum task_state { TASK_RUNNING = 0, TASK_SLEEPING = 1 };
static int schedule(struct task_struct *curr) { return curr->pid; }
'''
parser = Parser(C_LANGUAGE)
tree = parser.parse(src)
root = tree.root_node

def print_tree(node, src_bytes, depth=0):
    text = src_bytes[node.start_byte:min(node.end_byte, node.start_byte+40)]
    field_info = ''
    print('  '*depth + f'{node.type}  field_names={[node.field_name_for_child(i) for i in range(node.child_count)]}  text={repr(text.decode(errors=\"replace\"))}')
    for child in node.children:
        print_tree(child, src_bytes, depth+1)

for child in root.children:
    print_tree(child, src)
    print()
" 2>&1 | head -80

