# Test edge cases for pointer-return functions before writing the fix
from tree_sitter import Language, Parser, Node
import tree_sitter_c as tsc
C_LANGUAGE = Language(tsc.language())

src = b'''
int **double_ptr(void) { return 0; }
static inline int *single_ptr(size_t sz) { return 0; }
int plain(void) { return 0; }
void (*fn_ptr)(int) = 0;
'''
parser = Parser(C_LANGUAGE)
tree = parser.parse(src)
root = tree.root_node

def show_decl(decl, indent=0):
    if decl is None:
        print(' '*indent + 'None')
        return
    name = decl.child_by_field_name('declarator')
    print(' '*indent + f'{decl.type} → decl field: {name.type if name else None} ({name.text.decode() if name else \"\"})' )
    if name and name.type in ('pointer_declarator', 'function_declarator'):
        show_decl(name, indent+2)

for child in root.children:
    if child.type == 'function_definition':
        print('FN:', src[child.start_byte:child.end_byte][:50])
        decl = child.child_by_field_name('declarator')
        show_decl(decl)
        print()
" 2>&1

