/// Parse DWARF from a vmlinux binary and return functions, structs, and line entries.
///
/// Args:
///     path: Path to vmlinux (must have DWARF debug info).
///     verbose: Print progress every 1000 CUs.
///     functions_only: Skip structs and line entries (faster, for address-range lookup only).
///
/// Returns a dict with keys "functions", "structs", "line_entries".
#[pyfunction]
#[pyo3(signature = (path, verbose=false, functions_only=false))]
fn parse_dwarf(
    py: Python<'_>,
    path: &str,
    verbose: bool,
    functions_only: bool,
) -> PyResult<PyObject> {
    let (_data, sections) =
        load_sections(path).map_err(|e| PyRuntimeError::new_err(e))?;

    // Build a Dwarf reader from the section data
    let load_section = |id: SectionId| -> Result<EndianSlice<LittleEndian>, gimli::Error> {
        let name = id.name();
        Ok(get_section(&sections, name))
    };

    let dwarf = gimli::Dwarf::load(load_section)
        .map_err(|e| PyRuntimeError::new_err(format!("DWARF load error: {e}")))?;

    let mut all_functions: Vec<FunctionSym> = Vec::new();
    let mut all_structs: Vec<StructSym> = Vec::new();
    let mut all_lines: Vec<LineEntry> = Vec::new();

    let mut cu_iter = dwarf.units();
    let mut cu_count = 0u32;

    while let Ok(Some(header)) = cu_iter.next() {
        let unit = match dwarf.unit(header) {
            Ok(u) => u,
            Err(_) => continue,
        };

        cu_count += 1;
        if verbose && cu_count % 1000 == 0 {
            eprintln!(
                "[dwarf-rs] {cu_count} CUs, {} funcs, {} structs",
                all_functions.len(),
                all_structs.len()
            );
        }

        let file_index = build_file_index(&unit, &dwarf);
        extract_functions(&unit, &dwarf, &file_index, &mut all_functions);

        if !functions_only {
            extract_structs(&unit, &dwarf, &mut all_structs);
            extract_line_entries(&unit, &file_index, &mut all_lines);
        }
    }

    if verbose {
        eprintln!(
            "[dwarf-rs] Done: {} CUs, {} functions, {} structs, {} line entries",
            cu_count,
            all_functions.len(),
            all_structs.len(),
            all_lines.len()
        );
    }

    // Convert to Python objects
    let result = PyDict::new(py);

    let py_functions = PyList::empty(py);
    for f in &all_functions {
        let d = PyDict::new(py);
        d.set_item("name", &f.name)?;
        d.set_item("addr_start", f.addr_start)?;
        d.set_item("addr_end", f.addr_end)?;
        d.set_item("file_path", &f.file_path)?;
        d.set_item("line", f.line)?;
        py_functions.append(d)?;
    }
    result.set_item("functions", py_functions)?;

    let py_structs = PyList::empty(py);
    for s in &all_structs {
        let d = PyDict::new(py);
        d.set_item("name", &s.name)?;
        let fields = PyList::empty(py);
        // Fields list is empty for now (requires recursive DIE traversal)
        // — add in a follow-up; the struct name alone is sufficient for
        // KernelGraph struct-reference edges.
        d.set_item("fields", fields)?;
        py_structs.append(d)?;
    }
    result.set_item("structs", py_structs)?;

    let py_lines = PyList::empty(py);
    for le in &all_lines {
        let d = PyDict::new(py);
        d.set_item("address", le.address)?;
        d.set_item("file_path", &le.file_path)?;
        d.set_item("line", le.line)?;
        py_lines.append(d)?;
    }
    result.set_item("line_entries", py_lines)?;

    Ok(result.into())
}

/// Lightweight variant: extract only function address ranges.
/// Faster than parse_dwarf() because it skips structs and line tables.
#[pyfunction]
#[pyo3(signature = (path, verbose=false))]
fn get_function_ranges(py: Python<'_>, path: &str, verbose: bool) -> PyResult<PyObject> {
    parse_dwarf(py, path, verbose, true)
}

