    while let Ok(Some(child)) = children.next() {
        let entry = child.entry();
        let tag = entry.tag();
        if tag == gimli::DW_TAG_structure_type || tag == gimli::DW_TAG_union_type {
            if let Some(sym) = parse_struct(entry, unit, dwarf) {
                out.push(sym);
            }
        }
        // Don't recurse deep — top-level structs only (nested structs are
        // captured when the outer struct is parsed)
    }
}

fn parse_struct<R: Reader>(
    entry: &DebuggingInformationEntry<R>,
    unit: &Unit<R>,
    dwarf: &Dwarf<R>,
) -> Option<StructSym> {
    // Skip forward declarations
    if let Ok(Some(attr)) = entry.attr(gimli::DW_AT_declaration) {
        if let AttributeValue::Flag(true) = attr.value() {
