//! kernel_talk_dwarf_rs — Fast DWARF parser exposed to Python via PyO3.
//!
//! Parses DWARF debug information from a Linux vmlinux binary to extract:
//!   - Function symbols (DW_TAG_subprogram) with address ranges and source locations
//!   - Struct/union layouts (DW_TAG_structure_type, DW_TAG_union_type) with field offsets
//!   - Line number tables (file:line → PC address mapping)
//!
//! Python API:
//!   parse_dwarf(path: str, verbose: bool = False) -> dict
//!   get_function_ranges(path: str) -> dict   # functions only, fastest

use std::collections::HashMap;
use std::fs;

use gimli::{
    AttributeValue, Dwarf, EndianSlice, LittleEndian, SectionId, Unit,
};
use object::{Object, ObjectSection};
use pyo3::exceptions::PyRuntimeError;
use pyo3::prelude::*;
use pyo3::types::{PyDict, PyList};

// ─── Section loading ──────────────────────────────────────────────────────────

fn load_sections(path: &str) -> Result<HashMap<String, Vec<u8>>, String> {
    let data = fs::read(path).map_err(|e| format!("Cannot read {path}: {e}"))?;
    let obj = object::File::parse(data.as_slice())
        .map_err(|e| format!("Cannot parse ELF {path}: {e}"))?;

    let mut sections: HashMap<String, Vec<u8>> = HashMap::new();
    for section in obj.sections() {
        if let Ok(name) = section.name() {
            if name.starts_with(".debug_") {
                if let Ok(d) = section.data() {
                    sections.insert(name.to_string(), d.to_vec());
                }
            }
        }
    }
    Ok(sections)
}

fn get_section<'a>(
    sections: &'a HashMap<String, Vec<u8>>,
    name: &str,
) -> EndianSlice<'a, LittleEndian> {
    let data = sections.get(name).map(|v| v.as_slice()).unwrap_or(&[]);
    EndianSlice::new(data, LittleEndian)
}

// ─── Data types ───────────────────────────────────────────────────────────────

struct FunctionSym {
    name: String,
    addr_start: u64,
    addr_end: u64,
    file_path: String,
    line: u64,
}

struct StructSym {
    name: String,
}

struct LineEntry {
    address: u64,
    file_path: String,
    line: u64,
}

// ─── DWARF traversal ──────────────────────────────────────────────────────────

type MyReader<'a> = EndianSlice<'a, LittleEndian>;
type MyDwarf<'a> = Dwarf<MyReader<'a>>;
type MyUnit<'a> = Unit<MyReader<'a>>;

/// Build file-path index from a unit's line program header.
fn build_file_index(unit: &MyUnit<'_>, dwarf: &MyDwarf<'_>) -> Vec<String> {
    let mut index = vec![String::new()]; // index 0 = unused per DWARF spec

    let program = match &unit.line_program {
        Some(p) => p.clone(),
        None => return index,
    };

    let header = program.header();
    let comp_dir: String = header
        .comp_dir()
        .and_then(|v| v.to_string().ok())
        .map(|s| s.to_string())
        .unwrap_or_default();

    for file in header.file_names() {
        let dir: String = if let Some(dir_attr) = file.directory(header) {
            match dwarf.attr_string(unit, dir_attr) {
                Ok(s) => s.to_string().unwrap_or_default().to_string(),
                Err(_) => comp_dir.clone(),
            }
        } else {
            comp_dir.clone()
        };

        let fname: String = match dwarf.attr_string(unit, file.path_name()) {
            Ok(s) => s.to_string().unwrap_or_default().to_string(),
            Err(_) => String::new(),
        };

        let full = if dir.is_empty() || fname.starts_with('/') {
            fname
        } else {
            format!("{dir}/{fname}")
        };
        index.push(full);
    }
    index
}

/// Extract functions from a single unit via flat DIE iteration.
fn extract_functions_from_unit(
    unit: &MyUnit<'_>,
    dwarf: &MyDwarf<'_>,
    file_index: &[String],
    out: &mut Vec<FunctionSym>,
) {
    let mut entries = unit.entries();
    while let Ok(Some((_delta, entry))) = entries.next_dfs() {
        if entry.tag() != gimli::DW_TAG_subprogram {
            continue;
        }
        // Skip declarations
        if let Ok(Some(attr)) = entry.attr(gimli::DW_AT_declaration) {
            if let AttributeValue::Flag(true) = attr.value() {
                continue;
            }
        }
        // Must have a name
        let name = match entry.attr(gimli::DW_AT_name) {
            Ok(Some(attr)) => match dwarf.attr_string(unit, attr.value()) {
                Ok(s) => s.to_string().unwrap_or_default().to_string(),
                Err(_) => continue,
            },
            _ => continue,
        };
        if name.is_empty() {
            continue;
        }
        // Address
        let lo_pc = match entry.attr(gimli::DW_AT_low_pc) {
            Ok(Some(attr)) => match attr.value() {
                AttributeValue::Addr(v) => v,
                _ => continue,
            },
            _ => continue,
        };
        if lo_pc == 0 {
            continue;
        }
        let hi_pc = entry.attr(gimli::DW_AT_high_pc)
            .ok()
            .flatten()
            .and_then(|a| match a.value() {
                AttributeValue::Addr(v) => Some(v),
                AttributeValue::Udata(offset) => Some(lo_pc + offset),
                _ => None,
            })
            .unwrap_or(lo_pc);

        // Source location
        let file_idx = entry.attr(gimli::DW_AT_decl_file)
            .ok()
            .flatten()
            .and_then(|a| match a.value() {
                AttributeValue::FileIndex(v) => Some(v as usize),
                _ => None,
            })
            .unwrap_or(0);
        let file_path = file_index.get(file_idx).cloned().unwrap_or_default();

        let line = entry.attr(gimli::DW_AT_decl_line)
            .ok()
            .flatten()
            .and_then(|a| match a.value() {
                AttributeValue::Udata(v) => Some(v),
                _ => None,
            })
            .unwrap_or(0);

        out.push(FunctionSym { name, addr_start: lo_pc, addr_end: hi_pc, file_path, line });
    }
}

/// Extract struct/union names from a unit.
fn extract_structs_from_unit(
    unit: &MyUnit<'_>,
    dwarf: &MyDwarf<'_>,
    out: &mut Vec<StructSym>,
) {
    let mut entries = unit.entries();
    while let Ok(Some((_delta, entry))) = entries.next_dfs() {
        let tag = entry.tag();
        if tag != gimli::DW_TAG_structure_type && tag != gimli::DW_TAG_union_type {
            continue;
        }
        // Skip forward declarations
        if let Ok(Some(attr)) = entry.attr(gimli::DW_AT_declaration) {
            if let AttributeValue::Flag(true) = attr.value() {
                continue;
            }
        }
        let name = match entry.attr(gimli::DW_AT_name) {
            Ok(Some(attr)) => match dwarf.attr_string(unit, attr.value()) {
                Ok(s) => s.to_string().unwrap_or_default().to_string(),
                Err(_) => continue,
            },
            _ => continue,
        };
        if !name.is_empty() {
            out.push(StructSym { name });
        }
    }
}

/// Extract line number entries for a unit.
fn extract_lines_from_unit(
    unit: &MyUnit<'_>,
    file_index: &[String],
    out: &mut Vec<LineEntry>,
) {
    let program = match unit.line_program.clone() {
        Some(p) => p,
        None => return,
    };

    let mut rows = program.rows();
    while let Ok(Some((_header, row))) = rows.next_row() {
        if row.end_sequence() {
            continue;
        }
        let file_idx = row.file_index() as usize;
        let file_path = file_index.get(file_idx).cloned().unwrap_or_default();
        let line = row.line().map(|l| l.get()).unwrap_or(0);
        out.push(LineEntry { address: row.address(), file_path, line });
    }
}

// ─── PyO3 entry points ────────────────────────────────────────────────────────

#[pyfunction]
#[pyo3(signature = (path, verbose=false, functions_only=false))]
fn parse_dwarf(
    py: Python<'_>,
    path: &str,
    verbose: bool,
    functions_only: bool,
) -> PyResult<PyObject> {
    let sections = load_sections(path).map_err(PyRuntimeError::new_err)?;

    let load_section = |id: SectionId| -> Result<EndianSlice<LittleEndian>, gimli::Error> {
        Ok(get_section(&sections, id.name()))
    };
    let dwarf = gimli::Dwarf::load(load_section)
        .map_err(|e| PyRuntimeError::new_err(format!("DWARF load error: {e}")))?;

    let mut all_functions: Vec<FunctionSym> = Vec::new();
    let mut all_structs: Vec<StructSym> = Vec::new();
    let mut all_lines: Vec<LineEntry> = Vec::new();

    let mut cu_iter = dwarf.units();
    let mut cu_count = 0u32;

    while let Ok(Some(header)) = cu_iter.next() {
        let unit = match dwarf.unit(header) {
            Ok(u) => u,
            Err(_) => continue,
        };
        cu_count += 1;
        if verbose && cu_count % 1000 == 0 {
            eprintln!(
                "[dwarf-rs] {cu_count} CUs, {} funcs, {} structs",
                all_functions.len(), all_structs.len()
            );
        }

        let file_index = build_file_index(&unit, &dwarf);
        extract_functions_from_unit(&unit, &dwarf, &file_index, &mut all_functions);

        if !functions_only {
            extract_structs_from_unit(&unit, &dwarf, &mut all_structs);
            extract_lines_from_unit(&unit, &file_index, &mut all_lines);
        }
    }

    if verbose {
        eprintln!(
            "[dwarf-rs] Done: {} CUs, {} functions, {} structs, {} line entries",
            cu_count, all_functions.len(), all_structs.len(), all_lines.len()
        );
    }

    // Convert to Python dict
    let result = PyDict::new_bound(py);

    let py_functions = PyList::empty_bound(py);
    for f in &all_functions {
        let d = PyDict::new_bound(py);
        d.set_item("name", &f.name)?;
        d.set_item("addr_start", f.addr_start)?;
        d.set_item("addr_end", f.addr_end)?;
        d.set_item("file_path", &f.file_path)?;
        d.set_item("line", f.line)?;
        py_functions.append(&d)?;
    }
    result.set_item("functions", &py_functions)?;

    let py_structs = PyList::empty_bound(py);
    for s in &all_structs {
        let d = PyDict::new_bound(py);
        d.set_item("name", &s.name)?;
        d.set_item("fields", PyList::empty_bound(py))?;
        py_structs.append(&d)?;
    }
    result.set_item("structs", &py_structs)?;

    let py_lines = PyList::empty_bound(py);
    for le in &all_lines {
        let d = PyDict::new_bound(py);
        d.set_item("address", le.address)?;
        d.set_item("file_path", &le.file_path)?;
        d.set_item("line", le.line)?;
        py_lines.append(&d)?;
    }
    result.set_item("line_entries", &py_lines)?;

    Ok(result.into())
}

#[pyfunction]
#[pyo3(signature = (path, verbose=false))]
fn get_function_ranges(py: Python<'_>, path: &str, verbose: bool) -> PyResult<PyObject> {
    parse_dwarf(py, path, verbose, true)
}

#[pymodule]
fn kernel_talk_dwarf_rs(m: &Bound<'_, PyModule>) -> PyResult<()> {
    m.add_function(wrap_pyfunction!(parse_dwarf, m)?)?;
    m.add_function(wrap_pyfunction!(get_function_ranges, m)?)?;
    m.add("__version__", env!("CARGO_PKG_VERSION"))?;
    Ok(())
}
