 \subsubsection{Architecture}

 \begin{equation}
   f(\text{query}) = \ell_2\text{-norm}\!\left(\text{mean-pool}\!\left(\text{CodeBERT}(\text{query\_tokens})\right)\right) \in \mathbb{R}^{768}
 \end{equation}

